1	<script>
2	// This component was mainly created to solve the z-index problem on PelleRiftBar milestone hovering
3	// Because apparently making the z-index of PelleStrike change with its expanded/contracted state is bad.
4	// As such it may not be perfectly generalised. Changes should be made to generalise it more.
5	export default {
6	  name: "CustomizeableTooltip",
7	  props: {
8	    tooltipContentStyle: {
9	      type: Object,
10	      required: false,
11	      default: () => ({})
12	    },
13	    tooltipArrowStyle: {
14	      type: Object,
15	      required: false,
16	      default: () => ({})
17	    },
18	    left: {
19	      type: String,
20	      required: false,
21	      default: ""
22	    },
23	    top: {
24	      type: String,
25	      required: false,
26	      default: ""
27	    },
28	    right: {
29	      type: String,
30	      required: false,
31	      default: ""
32	    },
33	    bottom: {
34	      type: String,
35	      required: false,
36	      default: ""
37	    },
38	    contentClass: {
39	      type: String,
40	      required: false,
41	      default: ""
42	    },
43	    mode: {
44	      type: String,
45	      required: false,
46	      default: "top"
47	    },
48	    show: {
49	      type: Boolean,
50	      required: false
51	    }
52	  },
53	  data() {
54	    return {
55	      hovering: false,
56	      mainContent: null
57	    };
58	  },
59	  computed: {
60	    positionStyle() {
61	      return {
62	        left: this.left,
63	        top: this.top,
64	        right: this.right,
65	        bottom: this.bottom
66	      };
67	    },
68	    tooltipType() {
69	      return `c-tooltip--${this.mode}`;
70	    },
71	    contentTransform() {
72	      const axis = this.mode === "top" || this.mode === "bottom" ? "X" : "Y";
73	      return `translate${axis}(${this.showNegativeSign(axis)}50%)`;
74	    },
75	    tooltipTransform() {
76	      switch (this.mode) {
77	        case "top":
78	          return `translate(${this.showNegativeSign("X")}50%, -100%)`;
79	        case "bottom":
80	          return `translate(${this.showNegativeSign("X")}50%, 100%)`;
81	        case "right":
82	          return `translate(100%, ${this.showNegativeSign("Y")}50%)`;
83	        case "left":
84	          return `translate(-100%, ${this.showNegativeSign("Y")}50%)`;
85	        default:
86	          return "";
87	      }
88	    },
89	    showTooltip() {
90	      return this.show || this.hovering;
91	    }
92	  },
93	  methods: {
94	    showNegativeSign(axis) {
95	      if (axis === "X") {
96	        return this.left ? "-" : "";
97	      }
98	      return this.top ? "-" : "";
99	    },
100	  }
101	};
102	</script>
103	
104	<template>
105	  <div class="l-custom-tooltip">
106	    <div
107	      class="c-main-content"
108	      :class="contentClass"
109	      :style="{ ...positionStyle, transform: contentTransform }"
110	      @mouseenter="hovering = true"
111	      @mouseleave="hovering = false"
112	    >
113	      <slot name="mainContent" />
114	    </div>
115	    <div
116	      class="c-tooltip-content"
117	      :class=" {'c-tooltip-show': showTooltip, [tooltipType]: true } "
118	      :style="[tooltipContentStyle, positionStyle, { transform: tooltipTransform }]"
119	    >
120	      <slot name="tooltipContent" />
121	    </div>
122	    <div
123	      class="c-tooltip-arrow"
124	      :class=" {'c-tooltip-show': showTooltip, [tooltipType]: true } "
125	      :style="[tooltipArrowStyle, positionStyle, { transform: tooltipTransform }]"
126	    />
127	  </div>
128	</template>
