2	export default {
3	  name: "NewsTicker",
4	  data() {
5	    return {
6	      enableAnimation: false,
7	    };
8	  },
9	  computed: {
10	    lineClass() {
11	      return this.enableAnimation ? undefined : "c-disable-ticker-animation";
12	    }
13	  },
14	  beforeCreate() {
15	    this.recentTickers = [];
16	  },
17	  mounted() {
18	    document.addEventListener("visibilitychange", () => this.restart.bind(this));
19	    this.restart();
20	  },
21	  beforeDestroy() {
22	    this.clearTimeouts();
23	  },
24	  methods: {
25	    update() {
26	      if (this.currentNews?.dynamic) {
27	        this.$refs.line.innerHTML = this.currentNews.text;
28	      }
29	      this.enableAnimation = player.options.news.includeAnimated;
30	    },
31	    restart() {
32	      // TODO: Proper delay before ui is initialized
33	      if (!GameUI.initialized) {
34	        setTimeout(this.restart.bind(this), 100);
35	        return;
36	      }
37	      this.clearTimeouts();
38	      if (document.hidden) {
39	        return;
40	      }
41	      this.prepareNextMessage();
42	    },
43	    clearTimeouts() {
44	      clearTimeout(this.delayTimeout);
45	      clearTimeout(this.scrollTimeout);
46	    },
47	    prepareNextMessage() {
48	      const line = this.$refs.line;
49	      if (line === undefined) return;
50	
51	      const isUnlocked = news => news.unlocked || news.unlocked === undefined;
52	
53	      if (nextNewsMessageId && GameDatabase.news.find(message => message.id === nextNewsMessageId)) {
54	        this.currentNews = GameDatabase.news.find(message => message.id === nextNewsMessageId);
55	        nextNewsMessageId = undefined;
56	      } else if (this.currentNews && this.currentNews.id === "a236") {
57	        this.currentNews = GameDatabase.news
58	          .filter(message => message.isAdvertising && isUnlocked(message))
59	          .randomElement();
60	      } else {
61	        const isAI = Math.random() < player.options.news.AIChance;
62	        this.currentNews = GameDatabase.news
63	          .filter(message => message.id.includes("ai") === isAI)
64	          .filter(message => !this.recentTickers.includes(message) && isUnlocked(message))
65	          .randomElement();
66	        // Prevent tickers from repeating if they were seen recently
67	        this.recentTickers.push(this.currentNews.id);
68	        while (this.recentTickers.length > player.options.news.repeatBuffer) this.recentTickers.shift();
69	      }
70	      if (this.currentNews.reset) {
71	        this.currentNews.reset();
72	      }
73	
74	      line.innerHTML = this.currentNews.text;
75	
76	      line.style["transition-duration"] = "0ms";
77	      if (this.currentNews?.id === "a244" || this.currentNews?.id === "ai63") {
78	        line.style.transform = "translateX(-100%)";
79	      } else {
80	        line.style.transform = "translateX(0)";
81	      }
82	
83	      const DELAY = 1000;
84	      this.delayTimeout = setTimeout(this.scrollMessage.bind(this), DELAY);
85	    },
86	    scrollMessage() {
87	      const line = this.$refs.line;
88	
89	      // SCROLL_SPEED is in pixels per second
90	      const SCROLL_SPEED = player.options.news.speed * 100;
91	      const scrollDuration = (this.$refs.ticker.clientWidth + line.clientWidth) / SCROLL_SPEED;
92	
93	      line.style["transition-duration"] = `${scrollDuration}s`;
94	      if (this.currentNews && this.currentNews.id === "a244") {
95	        line.style.transform = "translateX(0)";
96	      } else {
97	        line.style.transform = "translateX(-100%)";
98	      }
99	
100	      NewsHandler.addSeenNews(this.currentNews.id);
101	      if (NewsHandler.uniqueTickersSeen >= 50) Achievement(22).unlock();
102	      player.news.totalSeen++;
103	
104	      this.scrollTimeout = setTimeout(this.prepareNextMessage.bind(this), scrollDuration * 1000);
105	    },
106	    onLineClick() {
107	      if (this.currentNews.onClick === undefined) {
108	        return;
109	      }
110	      SecretAchievement(24).unlock();
111	      const updatedText = this.currentNews.onClick();
112	      if (updatedText !== undefined) {
113	        this.$refs.line.innerHTML = updatedText;
114	      }
115	    }
116	  }
117	};
118	</script>
119	
120	<template>
121	  <div
122	    ref="ticker"
123	    class="c-news-ticker"
124	  >
