27	      type: Boolean,
28	      required: false,
29	    },
30	  },
31	  data() {
32	    return {
33	      canBuy: false,
34	      isBought: false,
35	      purchases: 0,
36	      currentTimeEstimate: new Decimal(0),
37	      projectedTimeEstimate: new Decimal(0),
38	      isCapped: false,
39	      hovering: false,
40	      hasRemnants: false,
41	      galaxyCap: 0,
42	      notAffordable: false
43	    };
44	  },
45	  computed: {
46	    config() {
47	      return this.upgrade.config;
48	    },
49	    effectText() {
50	      if (!this.config.formatEffect) return false;
51	      const prefix = this.isCapped ? "Capped:" : "Currently:";
52	      const formattedEffect = x => this.config.formatEffect(this.config.effect(x));
53	      const value = formattedEffect(this.purchases);
54	      const next = (!this.isCapped && this.hovering && this.canBuy)
55	        ? formattedEffect(this.purchases + 1)
56	        : undefined;
57	      return { prefix, value, next };
58	    },
59	    timeEstimate() {
60	      if (!this.hasTimeEstimate || !this.hasRemnants) return null;
61	      if (this.notAffordable) return "Never affordable due to Generated Galaxy cap";
62	      return this.currentTimeEstimate;
63	    },
64	    hasTimeEstimate() {
65	      return !(this.canBuy ||
66	        this.isBought ||
67	        this.isCapped ||
68	        (this.galaxyGenerator && this.config.currencyLabel !== "Galaxy")
69	      );
70	    },
71	    shouldEstimateImprovement() {
72	      return this.showImprovedEstimate && this.hasTimeEstimate;
73	    },
74	    estimateImprovement() {
75	      if (!this.shouldEstimateImprovement) return "";
76	      if (!Pelle.canArmageddon) return `${this.currentTimeEstimate}`;
77	      // If the improved value is still "> 1 year" then we only show it once
78	      if (this.projectedTimeEstimate.startsWith(">")) return this.projectedTimeEstimate;
79	      return `${this.currentTimeEstimate} ➜ ${this.projectedTimeEstimate}`;
80	    },
81	    estimateImprovementTooltipStyle() {
82	      const show = this.showImprovedEstimate && this.shouldEstimateImprovement;
83	      return {
84	        visibility: show ? "visible" : "hidden",
85	        opacity: show ? 1 : 0
86	      };
87	    }
88	  },
89	  methods: {
90	    update() {
91	      this.canBuy = this.upgrade.canBeBought && !this.faded;
92	      this.isBought = this.upgrade.isBought;
93	      this.isCapped = this.upgrade.isCapped;
94	      this.purchases = player.celestials.pelle.rebuyables[this.upgrade.config.id];
95	      this.currentTimeEstimate = TimeSpan
96	        .fromSeconds(this.secondsUntilCost(this.galaxyGenerator ? GalaxyGenerator.gainPerSecond
97	          : Pelle.realityShardGainPerSecond).toNumber())
98	        .toTimeEstimate();
99	      this.projectedTimeEstimate = TimeSpan
100	        .fromSeconds(this.secondsUntilCost(Pelle.nextRealityShardGain).toNumber())
101	        .toTimeEstimate();
102	      this.hasRemnants = Pelle.cel.remnants > 0;
103	      this.galaxyCap = GalaxyGenerator.generationCap;
104	      const genDB = GameDatabase.celestials.pelle.galaxyGeneratorUpgrades;
105	      this.notAffordable = (this.config === genDB.additive || this.config === genDB.multiplicative) &&
106	        (Decimal.gt(this.upgrade.cost, this.galaxyCap - GalaxyGenerator.generatedGalaxies + player.galaxies));
107	    },
108	    secondsUntilCost(rate) {
109	      const value = this.galaxyGenerator ? player.galaxies + GalaxyGenerator.galaxies : Currency.realityShards.value;
110	      return Decimal.sub(this.upgrade.cost, value).div(rate);
111	    },
112	  }
113	};
