1	<script>
2	import wordShift from "../../../../javascripts/core/wordShift";
3	
4	import EffectDisplay from "@/components/EffectDisplay";
5	import HintText from "@/components/HintText";
6	
7	export default {
8	  name: "NormalAchievement",
9	  components: {
10	    EffectDisplay,
11	    HintText
12	  },
13	  props: {
14	    achievement: {
15	      type: Object,
16	      required: true
17	    },
18	    isObscured: {
19	      type: Boolean,
20	      required: false
21	    }
22	  },
23	  data() {
24	    return {
25	      isDisabled: false,
26	      isUnlocked: false,
27	      isMouseOver: false,
28	      isCancer: false,
29	      showUnlockState: false,
30	      realityUnlocked: false,
31	      garbleTimer: 0,
32	      garbleKey: 0,
33	    };
34	  },
35	  computed: {
36	    id() {
37	      return this.achievement.id;
38	    },
39	    displayId() {
40	      return this.config.displayId ?? this.id;
41	    },
42	    config() {
43	      return this.achievement.config;
44	    },
45	    styleObject() {
46	      return {
47	        "background-position": `-${(this.achievement.column - 1) * 104}px -${(this.achievement.row - 1) * 104}px`
48	      };
49	    },
50	    classObject() {
51	      return {
52	        "o-achievement": true,
53	        "o-achievement--disabled": this.isDisabled,
54	        "o-achievement--locked": !this.isUnlocked && !this.isDisabled && !this.isObscured,
55	        "o-achievement--unlocked": this.isUnlocked,
56	        "o-achievement--waiting": !this.isUnlocked && this.isPreRealityAchievement && !this.isDisabled,
57	        "o-achievement--blink": !this.isUnlocked && this.id === 78 && !this.isDisabled,
58	        "o-achievement--normal": !this.isCancer && !this.isObscured,
59	        "o-achievement--cancer": this.isCancer && !this.isObscured,
60	        "o-achievement--hidden": this.isObscured,
61	      };
62	    },
63	    indicatorIconClass() {
64	      if (this.isUnlocked) return "fas fa-check";
65	      if (this.isPreRealityAchievement && !this.isDisabled) return "far fa-clock";
66	      return "fas fa-times";
67	    },
68	    indicatorClassObject() {
69	      return {
70	        "o-achievement__indicator": true,
71	        "o-achievement__indicator--disabled": this.isDisabled,
72	        "o-achievement__indicator--locked": !this.isUnlocked && !this.isPreRealityAchievement && !this.isDisabled,
73	        "o-achievement__indicator--waiting": !this.isUnlocked && this.isPreRealityAchievement && !this.isDisabled,
74	      };
75	    },
76	    isPreRealityAchievement() {
77	      return this.realityUnlocked && this.achievement.row <= 13;
78	    },
79	    // The garble templates themselves can be static, and shouldn't be recreated every render tick
80	    garbledNameTemplate() {
81	      return this.makeGarbledTemplate(this.config.name);
82	    },
83	    garbledIDTemplate() {
84	      return this.makeGarbledTemplate(this.displayId);
85	    },
86	    garbledDescriptionTemplate() {
87	      return this.makeGarbledTemplate(this.config.description);
88	    },
89	  },
90	  beforeDestroy() {
91	    clearTimeout(this.mouseOverInterval);
92	  },
93	  methods: {
94	    update() {
95	      this.isDisabled = Pelle.disabledAchievements.includes(this.id) && Pelle.isDoomed;
96	      this.isUnlocked = this.achievement.isUnlocked && !this.isDisabled;
97	      this.isCancer = Theme.current().name === "S4" || player.secretUnlocks.cancerAchievements;
98	      this.showUnlockState = player.options.showHintText.achievementUnlockStates;
99	      this.realityUnlocked = PlayerProgress.realityUnlocked();
100	
101	      this.processedName = this.processText(this.config.name, this.garbledNameTemplate);
102	      this.processedId = this.processText(this.displayId, this.garbledIDTemplate);
103	      this.processedDescription = this.processText(this.config.description, this.garbledDescriptionTemplate);
104	
105	      // This uses key-swapping to force the garbled achievements to re-render their text, because otherwise they
106	      // would remain static. Keys for non-garbled achievements won't change, and all keys remain unique.
107	      this.garbleTimer++;
108	      if (this.isObscured) {
109	        this.garbleKey = 10 * this.id + Math.floor(this.garbleTimer / 3);
110	      } else {
111	        this.garbleKey = this.id;
112	      }
113	    },
114	    onMouseEnter() {
115	      clearTimeout(this.mouseOverInterval);
116	      this.isMouseOver = true;
117	    },
118	    onMouseLeave() {
119	      this.mouseOverInterval = setTimeout(() => this.isMouseOver = false, 300);
120	    },
121	    // We don't want to expose the original text for Pelle achievements, so we generate a random string with the same
122	    // length of the original text in order to make something that fits reasonably within their respective places
123	    makeGarbledTemplate(input) {
124	      // Input might be either text or number
125	      const text = `${input}`;
126	      let garbled = "";
127	      for (let i = 0; i < text.length; i++) {
128	        if (text[i] === " ") garbled += " ";
129	        else {
130	          const n = text[i].charCodeAt();
131	          // Essentially seeded randomness so that the static parts of the randomized text are deterministic
132	          garbled += String.fromCharCode(33 + ((n * n + i * i) % 93));
133	        }
134	      }
135	      return garbled;
136	    },
137	    // When appropriate, garbles input text for achievements on the last row. Otherwise leaves it unchanged
138	    processText(unmodified, garbledTemplate) {
139	      if (!this.isObscured) return unmodified;
140	
141	      // The garbling effect often replaces spaces with non-spaces, which affects line length and can cause individual
142	      // lines to become long enough that they can't word-wrap. To address that, we take the template as a reference
143	      // and put spaces back into the same spots, ensuring that text can't overflow any worse than the original text
144	      const raw = wordShift.randomCrossWords(garbledTemplate);
145	      let modified = "";
146	      for (let i = 0; i < raw.length; i++) {
147	        if (garbledTemplate[i] === " ") modified += " ";
148	        else modified += raw[i];
149	      }
150	      return modified;
151	    }
152	  }
153	};
154	</script>
155	
156	<template>
157	  <div
158	    :class="classObject"
159	    :style="styleObject"
160	    @mouseenter="onMouseEnter"
161	    @mouseleave="onMouseLeave"
162	  >
163	    <HintText
164	      :key="garbleKey"
165	      type="achievements"
166	      class="l-hint-text--achievement"
167	    >
168	      {{ processedId }}
169	    </HintText>
170	    <div class="o-achievement__tooltip">
171	      <template v-if="isMouseOver">
172	        <div class="o-achievement__tooltip__name">
173	          {{ processedName }} ({{ processedId }})
174	        </div>
175	        <div class="o-achievement__tooltip__description">
176	          {{ processedDescription }}
177	        </div>
178	        <div
179	          v-if="config.reward"
180	          class="o-achievement__tooltip__reward"
181	        >
182	          <span
183	            v-if="!isObscured"
184	            :class="{ 'o-pelle-disabled': isDisabled }"
185	          >
186	            Reward: {{ config.reward }}
187	            <EffectDisplay
188	              v-if="config.formatEffect"
189	              br
190	              :config="config"
191	            />
192	          </span>
193	        </div>
194	      </template>
195	    </div>
196	    <div
197	      v-if="showUnlockState"
198	      :class="indicatorClassObject"
199	    >
200	      <i :class="indicatorIconClass" />
201	    </div>
202	  </div>
203	</template>
204	
205	<style scoped>
206	
207	</style>
208

1	<script>
2	import wordShift from "../../../../javascripts/core/wordShift";
3	
4	import PelleUpgrade from "./PelleUpgrade";
5	
6	export default {
7	  name: "GalaxyGeneratorPanel",
8	  components: {
9	    PelleUpgrade
10	  },
11	  data() {
12	    return {
13	      isUnlocked: false,
14	      galaxies: 0,
15	      generatedGalaxies: 0,
16	      galaxiesPerSecond: 0,
17	      cap: 0,
18	      isCapped: false,
19	      capRift: null,
20	      sacrificeActive: false,
21	      isCollapsed: false,
22	      barWidth: 0,
23	      capRiftName: "",
24	    };
25	  },
26	  computed: {
27	    collapseIcon() {
28	      return this.isCollapsed
29	        ? "fas fa-expand-arrows-alt"
30	        : "fas fa-compress-arrows-alt";
31	    },
32	    upgrades() {
33	      return GalaxyGeneratorUpgrades.all;
34	    },
35	    galaxyText() {
36	      let text = format(Math.max(this.galaxies, 0), 2);
37	      if (this.galaxies < 0) text += ` [${format(this.galaxies, 2)}]`;
38	      return text;
39	    },
40	    sacrificeText() {
41	      return this.capRift.galaxyGeneratorText.replace("$value", this.capRiftName);
42	    }
43	  },
44	  methods: {
45	    update() {
46	      this.isUnlocked = Pelle.hasGalaxyGenerator;
47	      this.isCapped = GalaxyGenerator.isCapped;
48	      this.isCollapsed = player.celestials.pelle.collapsed.galaxies && !this.isCapped;
49	      if (this.isCollapsed || !this.isUnlocked) return;
50	      this.galaxies = player.galaxies + GalaxyGenerator.galaxies;
51	      this.generatedGalaxies = GalaxyGenerator.generatedGalaxies;
52	      this.galaxiesPerSecond = GalaxyGenerator.gainPerSecond;
53	      this.cap = GalaxyGenerator.generationCap;
54	      this.capRift = GalaxyGenerator.capRift;
55	      this.sacrificeActive = GalaxyGenerator.sacrificeActive;
56	      this.barWidth = (this.isCapped ? this.capRift.reducedTo : this.generatedGalaxies / this.cap);
57	      this.capRiftName = wordShift.wordCycle(this.capRift.name);
58	    },
59	    increaseCap() {
60	      if (GalaxyGenerator.isCapped) GalaxyGenerator.startSacrifice();
61	    },
62	    toggleCollapse() {
63	      player.celestials.pelle.collapsed.galaxies = !this.isCollapsed;
64	    },
65	    unlock() {
