1	<script>
2	import GlyphTooltipEffect from "@/components/GlyphTooltipEffect";
3	
4	export default {
5	  name: "GlyphTooltip",
6	  components: {
7	    GlyphTooltipEffect
8	  },
9	  props: {
10	    type: {
11	      type: String,
12	      required: true
13	    },
14	    strength: {
15	      type: Number,
16	      required: true
17	    },
18	    level: {
19	      type: Number,
20	      required: true
21	    },
22	    effects: {
23	      type: Number,
24	      required: true
25	    },
26	    id: {
27	      type: Number,
28	      required: false,
29	      default: 0,
30	    },
31	    sacrificeReward: {
32	      type: Number,
33	      required: false,
34	      default: 0,
35	    },
36	    refineReward: {
37	      type: Number,
38	      required: false,
39	      default: 0,
40	    },
41	    uncappedRefineReward: {
42	      type: Number,
43	      required: false,
44	      default: 0,
45	    },
46	    currentAction: {
47	      type: String,
48	      required: true
49	    },
50	    scoreMode: {
51	      type: Number,
52	      required: true
53	    },
54	    showDeletionText: {
55	      type: Boolean,
56	      required: false,
57	      default: true,
58	    },
59	    displayLevel: {
60	      type: Number,
61	      required: false,
62	      default: 0,
63	    },
64	    changeWatcher: {
65	      type: Number,
66	      required: true
67	    }
68	  },
69	  data() {
70	    return {
71	      showChaosText: false,
72	      chaosDescription: ""
73	    };
74	  },
75	  computed: {
76	    onTouchDevice() {
77	      return GameUI.touchDevice;
78	    },
79	    effectiveLevel() {
80	      return this.displayLevel ? this.displayLevel : this.level;
81	    },
82	    sortedEffects() {
83	      return getGlyphEffectValuesFromBitmask(this.effects, this.effectiveLevel, this.strength, this.type)
84	        .filter(effect =>
85	          GlyphEffects[effect.id].isGenerated === generatedTypes.includes(this.type));
86	    },
87	    rarityInfo() {
88	      return getRarity(this.strength);
89	    },
90	    descriptionStyle() {
91	      let color = this.rarityInfo.color;
92	      if (this.type === "cursed") color = "black";
93	      if (this.type === "companion") color = GlyphTypes[this.type].color;
94	      return {
95	        color,
96	        "text-shadow": this.type === "cursed"
97	          ? undefined
98	          : `-0.1rem 0.1rem 0.1rem black, 0.1rem 0.1rem 0.1rem black,
99	            -0.1rem -0.1rem 0.1rem black, 0.1rem -0.1rem 0.1rem black,
100	            0 0 0.3rem ${color}`,
101	        animation: this.type === "reality" ? "a-reality-glyph-name-cycle 10s infinite" : undefined
102	      };
103	    },
104	    description() {
105	      const glyphName = `${this.type.capitalize()}`;
106	      switch (this.type) {
107	        case "companion":
108	          return "Companion Glyph";
109	        case "cursed":
110	          return "Cursed Glyph";
111	        case "reality":
112	          return `Pure Glyph of ${glyphName}`;
113	        default:
114	          return `${this.rarityInfo.name} Glyph of ${glyphName}`;
115	      }
116	    },
117	    isLevelCapped() {
118	      return this.displayLevel && this.displayLevel < this.level;
119	    },
120	    isLevelBoosted() {
121	      return this.displayLevel && this.displayLevel > this.level;
122	    },
123	    rarityText() {
124	      if (!GlyphTypes[this.type].hasRarity) return "";
125	      const strength = Pelle.isDoomed ? Pelle.glyphStrength : this.strength;
126	      return `| Rarity:
127	        <span style="color: ${this.rarityInfo.color}">${formatRarity(strengthToRarity(strength))}</span>`;
128	    },
129	    levelText() {
130	      if (this.type === "companion") return "";
131	      // eslint-disable-next-line no-nested-ternary
132	      const arrow = this.isLevelCapped
133	        ? "<i class='fas fa-sort-down'></i>"
134	        : (this.isLevelBoosted ? "<i class='fas fa-sort-up'></i>" : "");
135	      // eslint-disable-next-line no-nested-ternary
136	      const color = this.isLevelCapped
137	        ? "#ff4444"
138	        : (this.isLevelBoosted ? "#44FF44" : "");
139	      return `Level: <span style="color: ${color}">
140	              ${arrow}${formatInt(this.effectiveLevel)}${arrow}
141	              </span>`;
142	    },
143	    eventHandlers() {
144	      return GameUI.touchDevice ? {
145	        touchstart: this.touchStart,
146	        dragstart: this.dragStart,
147	        dragEnd: this.dragEnd,
148	      } : {};
149	    },
150	    glyphTooltipStyle() {
151	      // With computer mice, it's nice to just totally disable mouse events on the tooltip,
152	      // which reduces the chances for stupidity
153	      return {
154	        "pointer-events": this.onTouchDevice ? undefined : "none",
155	        "border-color": GlyphTypes[this.type].color,
156	        "box-shadow": `0 0 0.5rem ${GlyphTypes[this.type].color}, 0 0 0.5rem ${GlyphTypes[this.type].color} inset`,
157	        animation: this.type === "reality" ? "a-reality-glyph-tooltip-cycle 10s infinite" : undefined,
158	        color: this.type === "cursed" ? "black" : undefined,
159	        background: this.type === "cursed" ? "white" : undefined
160	      };
161	    },
162	    glyphHeaderStyle() {
163	      const isCursed = this.type === "cursed";
164	      const isReality = this.type === "reality";
165	
166	      let color = this.rarityInfo.color;
167	      if (isCursed) color = "black";
168	      if (this.type === "companion") color = GlyphTypes[this.type].color;
169	      return {
170	        "border-color": color,
171	        "box-shadow": `0 0 0.5rem 0.1rem ${color}, 0 0 0.8rem ${color} inset`,
172	        animation: isReality ? "a-reality-glyph-tooltip-header-cycle 10s infinite" : undefined,
173	        color: isCursed ? "black" : undefined,
174	        background: isCursed ? "white" : undefined
175	      };
176	    }
177	  },
178	  watch: {
179	    changeWatcher() {
180	      this.$recompute("sortedEffects");
181	    }
182	  },
183	  mounted() {
184	    // By attaching the tooltip to the body element, we make sure it ends up on top of anything
185	    // else, with no z order shenanigans
186	    document.body.appendChild(this.$el);
187	  },
188	  destroyed() {
189	    try {
190	      document.body.removeChild(this.$el);
191	    } catch (e) {
192	      // If the tooltip isn't visible, then it can't be removed on account of not being there in the first place.
193	      // Trying to remove it anyway causes an exception to be thrown but otherwise nothing seems to actually affect
194	      // the game. Nevertheless, including this try/catch no-op suppresses console error spam.
195	    }
196	  },
197	  methods: {
198	    update() {
199	      this.showChaosText = Pelle.specialGlyphEffect.isUnlocked;
200	      if (this.showChaosText) {
201	        this.chaosDescription = Pelle.getSpecialGlyphEffectDescription(this.type);
202	      }
203	    },
204	    touchStart() {
205	      // We _don't_ preventDefault here because we want the event to turn into a local
206	      // dragstart that we can intercept
207	      this.$parent.$emit("tooltip-touched");
208	    },
209	    dragStart(ev) {
210	      // Prevent dragging by tooltip on mobile
211	      ev.preventDefault();
212	      ev.stopPropagation();
213	    },
214	    dragEnd(ev) {
215	      ev.preventDefault();
216	      ev.stopPropagation();
217	    },
218	    removeGlyph() {
219	      GlyphSacrificeHandler.removeGlyph(Glyphs.findById(this.id), false);
220	    },
221	    sacrificeText() {
222	      if (this.type === "companion" || this.type === "cursed") return "";
223	      const powerText = `${format(this.sacrificeReward, 2, 2)}`;
224	      const isCurrentAction = this.currentAction === "sacrifice";
225	      return `<span style="font-weight: ${isCurrentAction ? "bold" : ""}; color: ${isCurrentAction ? "#ccc" : ""}">
226	              Sacrifice: ${powerText}
227	              </span>`;
228	    },
229	    refineText() {
230	      if (this.type === "companion" || this.type === "cursed" || this.type === "reality") return "";
231	      if (!AlchemyResource[this.type].isUnlocked) return "";
232	      let refinementText = `${format(this.uncappedRefineReward, 2, 2)} ${GLYPH_SYMBOLS[this.type]}`;
233	      if (this.uncappedRefineReward !== this.refineReward) {
234	        refinementText += ` (Actual value due to cap: ${format(this.refineReward, 2, 2)} ${GLYPH_SYMBOLS[this.type]})`;
235	      }
236	      const isCurrentAction = this.currentAction === "refine";
237	      return `<span style="font-weight: ${isCurrentAction ? "bold" : ""}; color: ${isCurrentAction ? "#ccc" : ""}">
238	              Refine: ${refinementText}
239	              </span>`;
240	    },
241	    scoreText() {
242	      if (this.type === "companion" || this.type === "cursed" || this.type === "reality") return "";
243	      const showFilterScoreModes = [AUTO_GLYPH_SCORE.SPECIFIED_EFFECT, AUTO_GLYPH_SCORE.EFFECT_SCORE];
244	      if (!showFilterScoreModes.includes(this.scoreMode)) return "";
245	      return `Score: ${format(AutoGlyphProcessor.filterValue(this.$parent.glyph), 1, 1)}`;
246	    }
247	  }
248	};
249	</script>
