1	<script>
2	// If you change this, try to keep the syntaxes and tenses the same to avoid solecisms
3	const GLYPH_NAMES = {
4	  companion: { name: "Huggable" },
5	  reality: { name: "Real" },
6	  music: { major: "Melodic", middling: "Chordal", minor: "Tuned" },
7	  effarig: { both: "Meta", glyph: "Stable", rm: "Mechanical", none: "Fragmented" },
8	  cursed: { major: "Cursed", middling: "Hexed", minor: "Jinxed" },
9	  power: { major: "Power", middling: "Mastered", minor: "Potential" },
10	  infinity: { major: "Infinity", middling: "Boundless", minor: "Immense" },
11	  replication: { major: "Replication", middling: "Simulated", minor: "Replicated" },
12	  time: { major: "Time", middling: "Chronal", minor: "Temporal" },
13	  dilation: { major: "Dilation", middling: "Attenuated", minor: "Diluted" },
14	};
15	
16	export default {
17	  name: "GlyphSetName",
18	  props: {
19	    glyphSet: {
20	      type: Array,
21	      required: true
22	    },
23	    forceColor: {
24	      type: Boolean,
25	      required: false,
26	      default: false
27	    }
28	  },
29	  data() {
30	    return {
31	      isColored: true,
32	      defaultOrder: ["power", "infinity", "replication", "time", "dilation"],
33	      multipleGlyphList: [
34	        { type: "power", perc: 0 },
35	        { type: "infinity", perc: 0 },
36	        { type: "replication", perc: 0 },
37	        { type: "time", perc: 0 },
38	        { type: "dilation", perc: 0 }
39	      ],
40	      activeSlotCount: 0
41	    };
42	  },
43	  computed: {
44	    setName() {
45	      this.sortGlyphList();
46	      let nameString = "";
47	
48	      // Start with Companion and Reality, add those to the start
49	      if (this.calculateGlyphPercent("companion")) {
50	        nameString += `${GLYPH_NAMES.companion.name} `;
51	      }
52	      if (this.calculateGlyphPercent("reality")) {
53	        nameString += `${GLYPH_NAMES.reality.name} `;
54	      }
55	
56	      // Now on to Music Glyphs - seperate from the others as they can be both Music and [type]
57	      if (this.musicGlyphPercent() === 100) {
58	        nameString += `${GLYPH_NAMES.music.major} `;
59	      } else if (this.musicGlyphPercent() >= 40) {
60	        nameString += `${GLYPH_NAMES.music.middling} `;
61	      } else if (this.musicGlyphPercent()) {
62	        nameString += `${GLYPH_NAMES.music.minor} `;
63	      }
64	
65	      // Both, RM, Glyph, Neither each have unique results
66	      const effarigRM = this.glyphSet.some(i => getSingleGlyphEffectFromBitmask("effarigrm", i));
67	      const effarigGlyph = this.glyphSet.some(i => getSingleGlyphEffectFromBitmask("effarigglyph", i));
68	      if (this.calculateGlyphPercent("effarig")) {
69	        if (effarigRM && effarigGlyph) nameString += `${GLYPH_NAMES.effarig.both} `;
70	        else if (effarigRM) nameString += `${GLYPH_NAMES.effarig.rm} `;
71	        else if (effarigGlyph) nameString += `${GLYPH_NAMES.effarig.glyph} `;
72	        else nameString += `${GLYPH_NAMES.effarig.none} `;
73	      }
74	
75	      // Cursed needs a special additional method of generating its names
76	      if (this.calculateGlyphPercent("cursed")) nameString += this.cursedName;
77	      else if (this.multipleGlyphList[0].perc) nameString += this.normalName;
78	
79	      return nameString;
80	    },
81	    cursedName() {
82	      const cursedPerc = this.calculateGlyphPercent("cursed");
83	      const main = GLYPH_NAMES.cursed;
84	      const fir = this.multipleGlyphList[0];
85	      const sec = this.multipleGlyphList[1];
86	      const thr = this.multipleGlyphList[2];
87	      if (cursedPerc === 100) {
88	        // All Cursed Glyphs should get something special.
89	        return `Fully ${main.major}`;
90	      }
91	      if (cursedPerc >= 75) {
92	        // Mostly Cursed Glyphs, but should mention the other.
93	        return `${main.major} ${this.getName(fir, "minor")}`;
94	      }
95	      if (cursedPerc >= 60) {
96	        // Have less Cursed Glyphs, so the name's changed, and might have a second now so need a case for that.
97	        return `${main.middling} ${this.getName(fir, "minor")}${this.getName(sec, "minor")}`;
98	      }
99	      if (cursedPerc >= 40) {
100	        // If we have a third normal Glyph, lets call it an Irregularity, otherwise specify the types.
101	        if (fir.perc >= 40) {
102	          return `${main.middling} ${this.getName(sec, "middling")}${this.getName(fir, "major")}`;
103	        }
104	        if (thr.perc) {
105	          return `${main.middling} Irregularity`;
106	        }
107	      }
108	      // If we only have the one Cursed Glyph, lets just add the normal name to it and avoid repetition.
109	      return `${main.minor} ${this.normalName}`;
110	    },
111	    normalName() {
112	      const fir = this.multipleGlyphList[0];
113	      const sec = this.multipleGlyphList[1];
114	      const thr = this.multipleGlyphList[2];
115	      if (fir.perc === 100) {
116	        // The only Glyph here is the one type so it should get a special name.
117	        return `Full ${this.getName(fir, "major")}`;
118	      }
119	      if (fir.perc >= 75) {
120	        // Two Glyphs, but its mainly the one type.
121	        return `${this.getName(sec, "middling")}${this.getName(fir, "major")}`;
122	      }
123	      if (fir.perc >= 60) {
124	        // Room for 2 other Glyphs off the main, so theres a case for each of them.
125	        return `${thr.perc
126	          ? `${this.getName(sec, "minor")}${this.getName(thr, "minor")}`
127	          : `${this.getName(sec, "middling")}`
128	        }${this.getName(fir, "major")}`;
129	      }
130	      if (fir.perc >= 40) {
131	        if (sec.perc >= 40) {
132	          if (thr.perc) {
133	            // If we have a 3rd type, lets also call it an Irregularity
134	            return `${this.getName(fir, "minor")}${this.getName(sec, "minor")}Irregularity`;
135	          }
136	          // Essentially means the same amount for both, so give them the same name.
137	          return `${this.getName(fir, "minor")}${this.getName(sec, "minor")}`;
138	        }
139	        // Second Glyph is less than the first meaning a different name, and if we also have a third, call it Blend.
140	        return `${this.getName(fir, "middling")}${thr.perc ? "Blend" : `${this.getName(sec, "minor")}`}`;
141	      }
142	      if (thr.perc) {
143	        // This means we have 3 different Glyphs, with only one Glyph of each.
144	        if (!(this.calculateGlyphPercent("reality") || this.calculateGlyphPercent("effarig") ||
145	          this.calculateGlyphPercent("cursed"))) {
146	          // If it doesn't have Reality, Effarig, or Cursed Glyphs, call it Irregular Jumble, otherwise call it Jumble.
147	          return "Irregular Jumble";
148	        }
149	        return "Jumble";
150	      }
151	      // This means we don't have 3 different Glyphs, but dont have 2 of one type.
152	      return `${this.getName(fir, "minor")}${this.getName(sec, "minor")}`;
153	    },
154	    mainGlyphName() {
155	      // This returns the type of Glyph that we want for color determinations.
156	      // The priority is Cursed > Companion > Reality > 60% or more of normal Glyphs > Effarig > any normal Glyph.
157	      if (this.calculateGlyphPercent("cursed")) return GlyphTypes.cursed;
158	      if (this.calculateGlyphPercent("companion")) return GlyphTypes.companion;
159	      if (this.calculateGlyphPercent("reality")) return GlyphTypes.reality;
160	      if (this.multipleGlyphList[0].perc >= 60) return GlyphTypes[this.multipleGlyphList[0].type];
161	      if (this.calculateGlyphPercent("effarig")) return GlyphTypes.effarig;
162	      return GlyphTypes[this.multipleGlyphList[0].type];
163	    },
164	    percentPerGlyph() {
165	      // We need to max glyphset length here because Doomed alters the active glyph slots to 0, which breaks stuff
166	      // in the calculation because we're dividing by 0
167	      return 100 / Math.max(this.activeSlotCount, this.glyphSet.length);
168	    },
169	    textColor() {
170	      // If its cursed, we want its color to be #5151EC, because by default its black, which can be unreadable.
171	      // If we have greater than or equal to 60% of our Glyphs as Music Glyphs, give us the Music Glyph color.
172	      // If we have 3 types of Glyphs, and none of them have more than 25% total, lets get a copper color.
173	      // And if we have none of the above (which is most common), lets get the color of the main Glyph.
174	      if (this.mainGlyphName.id === "cursed") return "#5151EC";
175	      if (this.musicGlyphPercent() >= 60) return "#FF80AB";
176	      if (this.multipleGlyphList[1].perc && this.multipleGlyphList[2].perc && this.multipleGlyphList[0].perc <= 25) {
177	        return "#C46200";
178	      }
179	      return this.mainGlyphName.color;
180	    },
181	    textStyle() {
182	      this.$recompute("mainGlyphName");
183	      // If you have the player option to not show color enabled, and this isn't a special case forcing color, return {}
184	      if (!this.isColored && !this.forceColor) return {};
185	      // Otherwise, lets set the shadow to be 4, each offset to a different corner, and bluring by 1px,
186	      // then bluring by 3px with no offset with the same color as the text.
187	      // If its a Reality Glyph, assign it Reality Glyph's animation.
188	      return {
189	        color: this.textColor,
190	        "text-shadow": `-1px 1px 1px var(--color-text-base), 1px 1px 1px var(--color-text-base),
191	                        -1px -1px 1px var(--color-text-base), 1px -1px 1px var(--color-text-base),
192	                        0 0 3px ${this.textColor}`,
193	        animation: this.mainGlyphName.id === "reality" ? "a-reality-glyph-description-cycle 10s infinite" : undefined,
194	      };
195	    }
196	  },
197	  created() {
198	    this.on$(GAME_EVENT.GLYPHS_CHANGED, this.sortGlyphList);
199	    this.sortGlyphList();
200	  },
201	  methods: {
202	    update() {
203	      this.isColored = player.options.glyphTextColors;
204	      this.activeSlotCount = Glyphs.activeSlotCount;
205	    },
206	    calculateGlyphPercent(name) {
207	      // Take the amount of a type of glyph in the set, divide by the maximum number of glyphs, then * 100 to get %
208	      return this.glyphSet.filter(i => i.type === name).length * this.percentPerGlyph;
209	    },
210	    musicGlyphPercent() {
211	      // Music Glyphs are tricky to get, have to search .symbol === "key266b"
