213	    },
214	    sortGlyphList() {
215	      // Get the percent for each type, then sort it based on type and then default order, to make it consistent
216	      this.$recompute("textColor");
217	      this.multipleGlyphList.forEach(i => i.perc = this.calculateGlyphPercent(i.type));
218	      this.multipleGlyphList.sort((a, b) => (a.perc === b.perc
219	        ? this.defaultOrder.indexOf(a.type) - this.defaultOrder.indexOf(b.type)
220	        : b.perc - a.perc));
221	    },
222	    getName(position, type) {
223	      // If the position.perc is 0, return an empty string, and if it does, return a string from GLYPH_NAMES
