1	<script>
2	import wordShift from "../../../../javascripts/core/wordShift";
3	
4	import CustomizeableTooltip from "@/components/CustomizeableTooltip";
5	
6	export default {
7	  name: "PelleRiftBar",
8	  components: {
9	    CustomizeableTooltip
10	  },
11	  props: {
12	    rift: {
13	      type: Object,
14	      required: true
15	    },
16	  },
17	  data() {
18	    return {
19	      isActive: false,
20	      isMaxed: false,
21	      percentage: 0,
22	      reducedTo: 0,
23	      hasEffectiveFill: false,
24	      selectedHoverMilestone: this.rift.milestones[0],
25	      // Converts 1 rem to number of px
26	      remToPx: parseInt(getComputedStyle(document.documentElement).fontSize, 10),
27	      effects: [],
28	      isDark: false,
29	      decayText: ""
30	    };
31	  },
32	  computed: {
33	    tooltipContentStyle() {
34	      const hasMilestone = this.hasMilestone(this.selectedHoverMilestone);
35	      const baseColor = this.isDark ? "#111111" : "var(--color-base)";
36	      return {
37	        width: "20rem",
38	        border: "0.1rem solid var(--color-pelle--base)",
39	        backgroundColor: hasMilestone ? "var(--color-pelle--base)" : baseColor,
40	        color: hasMilestone ? "black" : "var(--color-text)",
41	        fontSize: "1.1rem",
42	        fontWeight: "bold",
43	        zIndex: 4,
44	        boxShadow: hasMilestone ? " 0 0 0.1rem 0.1rem black" : ""
45	      };
46	    },
47	    tooltipArrowStyle() {
48	      return {
49	        borderTop: "0.55rem solid var(--color-pelle--base)"
50	      };
51	    }
52	  },
53	  created() {
54	    this.isDark = Themes.find(player.options.theme).isDark();
55	  },
56	  methods: {
57	    update() {
58	      const rift = this.rift;
59	      this.effects = rift.effects;
60	      this.isActive = rift.isActive;
61	      this.isMaxed = rift.isMaxed || Pelle.hasGalaxyGenerator;
62	      this.percentage = rift.percentage;
63	      this.reducedTo = rift.reducedTo;
64	      this.hasEffectiveFill = rift.config.key === "decay" && PelleRifts.chaos.milestones[0].canBeApplied;
65	
66	      // If it's chaos, update decay text
67	      if (rift.id === 3) this.decayText = wordShift.wordCycle(PelleRifts.decay.name);
68	    },
69	    hasMilestone(ms) {
70	      return ms.canBeApplied;
71	    },
72	    milestoneResourceText(rift, milestone) {
73	      return `${formatPercents(milestone.requirement)}
74	      (${this.formatRift(rift.config.percentageToFill(milestone.requirement))} \
75	      ${rift.id === 3 ? this.decayText : rift.drainResource})`;
76	    },
77	    milestoneDescriptionText(milestone) {
78	      if (typeof milestone.description === "string") return milestone.description;
79	      return milestone.description();
80	    },
81	    // One-off formatting function; needs to format large Decimals and a small number assumed to be a percentage
82	    formatRift(value) {
83	      return typeof value === "number" ? formatPercents(value, 3) : format(value, 2);
84	    },
85	    toggle() {
86	      if (!this.isMaxed) this.rift.toggle();
87	    },
88	    barOverlay() {
89	      const overfill = this.percentage > 1;
90	      return {
91	        "o-pelle-rift-bar-permanent": !overfill && this.hasEffectiveFill,
92	        "o-pelle-rift-bar-overfilled": overfill,
93	      };
94	    },
95	    handleMilestoneRequirementTooltipDisplay(event) {
96	      const mouseX = event.clientX - this.$refs.pelleRiftBar.getBoundingClientRect().x;
97	
98	      const milestonesCloseTo = this.rift.milestones.filter(m => {
99	        // Gets distance from the milestone bar in terms of rem
100	        // 31.6: the width of the bar is 32 rem, but adjusted to a border with 0.2rem on both sides
101	        const dist = Math.abs((m.requirement * 31.6) - mouseX / this.remToPx);
102	        if (dist < 1) m.dist = dist;
103	        return dist < 1;
104	      }).map(m => {
105	        const dist = m.dist;
106	        delete m.dist;
107	        // Temporarily store the distance without recalculation to sort the list by distance
108	        // and get the closest item
109	        return { dist, m };
110	      });
111	
112	      if (milestonesCloseTo.length) {
113	        this.selectedHoverMilestone = milestonesCloseTo.sort((a, b) => a.dist - b.dist)[0].m;
114	      }
115	    }
116	  }
117	};
118	</script>
119	
