const Vue = require('/app/node_modules/vue/dist/vue.common.dev.js');

let renderCount = 0;
let liveExternalValue = 0; // simulates ms.canBeApplied changing behind the scenes, not tracked by Vue

const vm = new Vue({
  data() {
    return {
      effects: []
    };
  },
  render(h) {
    renderCount++;
    // simulate reading a live non-reactive external value during render
    const snapshot = liveExternalValue;
    return h('div', `${this.effects.length} ${snapshot}`);
  }
});

function getFreshArray() {
  // simulate rift.effects always returning a brand new array reference
  return [Math.random()];
}

let ticks = 0;
const interval = setInterval(() => {
  ticks++;
  liveExternalValue = ticks; // this changes every tick but ISN'T a reactive data prop
  vm.effects = getFreshArray(); // reassign brand-new array reference every tick
  if (ticks === 5) {
    clearInterval(interval);
    setTimeout(() => {
      console.log('renderCount:', renderCount, 'ticks:', ticks);
      console.log('last rendered value (from vm._vnode):', vm._vnode.text);
    }, 50);
  }
}, 30);
EOF
